import test from "node:test";import assert from "node:assert/strict";import {createServer} from "node:http";import {execFileSync} from "node:child_process";import {existsSync,mkdtempSync,readFileSync,rmSync,writeFileSync,mkdirSync} from "node:fs";import {tmpdir} from "node:os";import {dirname,join} from "node:path";import {atomicWrite,computeWorktreeStateHash,provenancePaths,sha256,validityWindow} from "@print-engineer/openrouter-free-selector";import {buildReviewProducer,openRouterConfig,planReviewProducer,runBuildProducer,runPlanProducer,selectOpenRouter,type ProvenanceOps} from "../src/core.js";import {dispatchControllerCommand,runNormalFallbackExecution} from "../src/index.js";import {SdkCodexExecutor} from "../src/codex-executor.js";import {statusLines} from "../src/provider-decision.js";
test("status is safe and inference-free data",()=>{const lines=statusLines("auto",{auth:false,planSupported:false,quota:"unknown",preferredModel:"unknown"},true);assert.ok(lines.includes("auto_decision=openrouter-free"));assert.ok(lines.every(x=>!x.includes("secret")&&!x.includes("plus")))});
