function ops(root:string,execute:()=>Promise<void>,planHashes:string[],states:string[],persist?:(path:string,value:unknown)=>void){let pi=0,si=0;const writes:any[]=[];const value:ProvenanceOps={lock:join(root,"lock"),planRecord:join(root,"plan.json"),buildRecord:join(root,"build.json"),readPlan:status=>{const hash=planHashes[Math.min(pi++,planHashes.length-1)];if(hash==="invalid")throw new Error("INVALID_PLAN_ARTIFACT");return{canonical:"plans/x.md",hash}},stateHash:()=>states[Math.min(si++,states.length-1)],execute,write:(p,v)=>{writes.push([p,v]);(persist??((path:string,value:unknown)=>atomicWrite(path,value)))(p,v)}};return{value,writes};}
test("PLAN producer writes only after successful changed valid artifact",async()=>{const root=mkdtempSync(join(tmpdir(),"plan-tx-"));try{const good=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[]);const record=await runPlanProducer("v/a:free",good.value);assert.equal(record.plan_sha256,"b".repeat(64));assert.equal(good.writes.length,1);for(const scenario of [{run:async()=>{throw new Error("fail")},hashes:["a".repeat(64),"b".repeat(64)]},{run:async()=>{},hashes:["a".repeat(64),"a".repeat(64)]},{run:async()=>{},hashes:["a".repeat(64),"invalid"]}]){const x=ops(root,scenario.run,scenario.hashes,[]);await assert.rejects(()=>runPlanProducer("v/a:free",x.value));assert.equal(x.writes.length,0)}}finally{rmSync(root,{recursive:true,force:true})}});
test("later PLAN revision replaces exact producer and approval excludes exact hash",async()=>{const root=mkdtempSync(join(tmpdir(),"plan-revision-"));try{const x=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[]);await runPlanProducer("v/a:free",x.value);const y=ops(root,async()=>{},["b".repeat(64),"c".repeat(64)],[]);await runPlanProducer("v/b:free",y.value);assert.equal(await planReviewProducer(y.value.planRecord,{canonical:"plans/x.md",hash:"c".repeat(64)}),"v/b:free");await assert.rejects(()=>planReviewProducer(y.value.planRecord,{canonical:"plans/x.md",hash:"d".repeat(64)}),/PLAN_PRODUCER_UNKNOWN/)}finally{rmSync(root,{recursive:true,force:true})}});
test("BUILD producer writes only after successful changed state",async()=>{const root=mkdtempSync(join(tmpdir(),"build-tx-"));try{const good=ops(root,async()=>{},["a".repeat(64),"a".repeat(64)],["1".repeat(64),"2".repeat(64)]);const record=await runBuildProducer("v/a:free",good.value);assert.equal(record.worktree_state_sha256,"2".repeat(64));assert.equal(good.writes.length,1);for(const scenario of [{run:async()=>{throw new Error("fail")},states:["1".repeat(64),"2".repeat(64)]},{run:async()=>{},states:["1".repeat(64),"1".repeat(64)]}]){const x=ops(root,scenario.run,["a".repeat(64),"a".repeat(64)],scenario.states);await assert.rejects(()=>runBuildProducer("v/a:free",x.value));assert.equal(x.writes.length,0)}}finally{rmSync(root,{recursive:true,force:true})}});
test("BUILD review requires exact plan and state producer",async()=>{const root=mkdtempSync(join(tmpdir(),"build-review-"));try{const path=join(root,"build.json"),record={schema_version:1,kind:"build_producer",plan_path:"plans/x.md",plan_sha256:"a".repeat(64),worktree_state_sha256:"b".repeat(64),model_id:"v/a:free"};atomicWrite(path,record);assert.equal(await buildReviewProducer(path,{canonical:"plans/x.md",hash:"a".repeat(64)},"b".repeat(64)),"v/a:free");await assert.rejects(()=>buildReviewProducer(path,{canonical:"plans/x.md",hash:"a".repeat(64)},"c".repeat(64)),/BUILD_PRODUCER_UNKNOWN/)}finally{rmSync(root,{recursive:true,force:true})}});
test("PLAN and BUILD mutation locks reject concurrency and release on failure",async()=>{const root=mkdtempSync(join(tmpdir(),"tx-lock-"));try{let release!:()=>void;const gate=new Promise<void>(r=>release=r);const first=ops(root,async()=>gate,["a".repeat(64),"b".repeat(64)],[]);const pending=runPlanProducer("v/a:free",first.value);const second=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[]);await assert.rejects(()=>runPlanProducer("v/b:free",second.value),/SELECTOR_EXECUTION_LOCKED/);release();await pending;const failed=ops(root,async()=>{throw new Error("boom")},["a".repeat(64)],[]);await assert.rejects(()=>runPlanProducer("v/a:free",failed.value));const after=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[]);await runPlanProducer("v/a:free",after.value)}finally{rmSync(root,{recursive:true,force:true})}});
test("normal selection requires compatibility and never tries candidate two after preflight",async()=>{const now=new Date("2026-08-19T00:00:00.000Z"),entry={schema_version:1,entries:[{model_id:"v/a:free",codex_sdk_version:"0.147.0",provider_id:"openrouter",wire_api:"responses",validated_at:now.toISOString(),valid_until:"2026-09-18T00:00:00.000Z"}]};const model=(id:string)=>({id,pricing:{prompt:"0",completion:"0",request:"0"},architecture:{input_modalities:["text"],output_modalities:["text"]},context_length:32768,top_provider:{context_length:32768},supported_parameters:["tools"],expiration_date:null});const root=mkdtempSync(join(tmpdir(),"selection-"));try{const registry=join(root,"registry.json");atomicWrite(registry,entry);let calls=0;const fetcher=async(input:string)=>{calls++;return new Response(JSON.stringify(input.includes("/model/")?{data:{...model("v/a:free"),pricing:{prompt:"1",completion:"0",request:"0"}}}:{data:[model("v/a:free"),model("v/b:free")],total_count:2}),{status:200})};await assert.rejects(()=>selectOpenRouter({phase:"build",key:"synthetic",fetcher,registryPath:registry,now}),/PREFLIGHT/);assert.equal(calls,2)}finally{rmSync(root,{recursive:true,force:true})}});
test("producer lock covers pre-state, thread execution, validation, and persistence",async()=>{const root=mkdtempSync(join(tmpdir(),"lock-order-"));try{const lock=join(root,"lock"),events:string[]=[];let planReads=0,stateReads=0;const opsBase={lock,planRecord:join(root,"plan.json"),buildRecord:join(root,"build.json"),readPlan:(status:"PROPOSED"|"APPROVED")=>{assert.equal(existsSync(lock),true);events.push(`read-plan-${status}`);return{canonical:"plans/x.md",hash:status==="PROPOSED"?(planReads++?"b":"a"):"a"};},stateHash:()=>{assert.equal(existsSync(lock),true);events.push("state");return stateReads++?"2":"1";},write:(path:string,value:unknown)=>{assert.equal(existsSync(lock),true);events.push("write");atomicWrite(path,value);}} as any;const plan={...opsBase,execute:async()=>{assert.equal(existsSync(lock),true);events.push("thread");}};await runPlanProducer("v/a:free",plan);assert.deepEqual(events,["read-plan-PROPOSED","thread","read-plan-PROPOSED","write"]);events.length=0;stateReads=0;const build={...opsBase,execute:async()=>{assert.equal(existsSync(lock),true);events.push("thread");}};await runBuildProducer("v/a:free",build);assert.deepEqual(events,["read-plan-APPROVED","state","thread","state","read-plan-APPROVED","write"]);assert.equal(existsSync(lock),false)}finally{rmSync(root,{recursive:true,force:true})}});
test("producer persistence failure releases PLAN and BUILD locks for subsequent acquisition",async()=>{const root=mkdtempSync(join(tmpdir(),"persist-lock-"));try{const failing=(path:string)=>{assert.equal(existsSync(join(root,"lock")),true);throw new Error("PERSISTENCE_FAILED")};const plan=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[],failing);await assert.rejects(()=>runPlanProducer("v/a:free",plan.value),/PERSISTENCE_FAILED/);assert.equal(plan.writes.length,1);assert.equal(existsSync(join(root,"plan.json")),false);const planAgain=ops(root,async()=>{},["a".repeat(64),"b".repeat(64)],[]);await runPlanProducer("v/a:free",planAgain.value);assert.equal(existsSync(join(root,"lock")),false);const build=ops(root,async()=>{},["a".repeat(64),"a".repeat(64)],["1".repeat(64),"2".repeat(64)],failing);await assert.rejects(()=>runBuildProducer("v/a:free",build.value),/PERSISTENCE_FAILED/);assert.equal(build.writes.length,1);assert.equal(existsSync(join(root,"build.json")),false);const buildAgain=ops(root,async()=>{},["a".repeat(64),"a".repeat(64)],["1".repeat(64),"2".repeat(64)],undefined);await runBuildProducer("v/a:free",buildAgain.value);assert.equal(existsSync(join(root,"lock")),false)}finally{rmSync(root,{recursive:true,force:true})}});
function gitTestRepo(){const root=mkdtempSync(join(tmpdir(),"dispatch-"));execFileSync("git",["init","-q"],{cwd:root});writeFileSync(join(root,".git","info","exclude"),"registry.json\n");mkdirSync(join(root,"plans"));writeFileSync(join(root,"task.md"),"task");writeFileSync(join(root,"plans","x.md"),"Status: APPROVED\n");return root;}
function selectorModel(id:string){return{id,pricing:{prompt:"0",completion:"0",request:"0"},architecture:{input_modalities:["text"],output_modalities:["text"]},context_length:32768,top_provider:{context_length:32768},supported_parameters:["tools"],expiration_date:null};}
function selectorRegistry(ids:string[]){const now=new Date(),window=validityWindow(now);return{schema_version:1,entries:ids.map(model_id=>({model_id,codex_sdk_version:"0.147.0",provider_id:"openrouter",wire_api:"responses",...window}))};}
function ensureBuildProducer(root:string,modelId="vendor/a:free"){const planPath="plans/x.md",paths=provenancePaths(root,planPath),planHash=sha256(readFileSync(join(root,"plans","x.md")));atomicWrite(paths.build,{schema_version:1,kind:"build_producer",plan_path:planPath,plan_sha256:planHash,worktree_state_sha256:computeWorktreeStateHash(root),model_id:modelId});return paths;}
type SideEffectCounters={codexExecutionCount:number;producerWriteCount:number;registryWriteCount:number;lockAcquisitionCount:number;gitMutationCount:number};
function sideEffectCounters():SideEffectCounters{return{codexExecutionCount:0,producerWriteCount:0,registryWriteCount:0,lockAcquisitionCount:0,gitMutationCount:0};}
function assertNoSelectOnlySideEffects(c:SideEffectCounters){assert.deepEqual(c,{codexExecutionCount:0,producerWriteCount:0,registryWriteCount:0,lockAcquisitionCount:0,gitMutationCount:0});}
async function dispatchSelectOnly(root:string,registryPath:string,fetcher:(input:string)=>Promise<Response>,producerModel="vendor/a:free",counters=sideEffectCounters()){ensureBuildProducer(root,producerModel);const executor:any={execute:async()=>{counters.codexExecutionCount++;throw new Error("SELECT_ONLY_STARTED_CODEX")}};try{return await dispatchControllerCommand(["--select-only"],{CODEX_PROVIDER_MODE:"openrouter-free",MODEL_WORKDIR:root,MODEL_TASK_FILE:"task.md",CODEX_PHASE:"review",CODEX_REVIEW_TARGET:"implementation",MODEL_PLAN_PATH:"plans/x.md",OPENROUTER_API_KEY:"synthetic"},{fetcher:fetcher as typeof fetch,registryPath,validateWorktree:w=>w,executor});}finally{assertNoSelectOnlySideEffects(counters);}}
test("actual CLI select-only dispatch uses selector, exclusion, registry, and preflight without mutation",async()=>{const root=gitTestRepo();try{const planPath="plans/x.md",paths=provenancePaths(root,planPath),planHash=sha256(readFileSync(join(root,"plans","x.md"))),stateHash=computeWorktreeStateHash(root);atomicWrite(paths.build,{schema_version:1,kind:"build_producer",plan_path:planPath,plan_sha256:planHash,worktree_state_sha256:stateHash,model_id:"vendor/a:free"});const registry=join(root,"registry.json");atomicWrite(registry,selectorRegistry(["vendor/a:free","vendor/b:free"]));const beforeRegistry=readFileSync(registry,"utf8"),beforeProducer=readFileSync(paths.build,"utf8"),beforeHash=computeWorktreeStateHash(root),urls:string[]=[];const fetcher=async(input:string)=>{urls.push(input);return new Response(JSON.stringify(input.includes("/model/")?{data:selectorModel("vendor/b:free")}:{data:[selectorModel("vendor/a:free"),selectorModel("vendor/b:free")],total_count:2}),{status:200})};const result=await dispatchSelectOnly(root,registry,fetcher);const afterHash=computeWorktreeStateHash(root);assert.ok(result?.includes("model=vendor/b:free"));assert.equal(afterHash,beforeHash);assert.deepEqual(urls,["https://openrouter.ai/api/v1/models?supported_parameters=tools&input_modalities=text&output_modalities=text&context=32768&max_price=0&max_output_price=0&sort=intelligence-high-to-low&min_coding_index=0","https://openrouter.ai/api/v1/model/vendor/b%3Afree"]);assert.equal(readFileSync(registry,"utf8"),beforeRegistry);assert.equal(readFileSync(paths.build,"utf8"),beforeProducer);assert.equal(existsSync(paths.lock),false)}finally{rmSync(root,{recursive:true,force:true})}});
test("actual CLI select-only dispatch stops on final preflight failure without candidate-two fallback",async()=>{const root=gitTestRepo();try{const paths=provenancePaths(root,"plans/x.md"),planHash=sha256(readFileSync(join(root,"plans","x.md"))),stateHash=computeWorktreeStateHash(root);atomicWrite(paths.build,{schema_version:1,kind:"build_producer",plan_path:"plans/x.md",plan_sha256:planHash,worktree_state_sha256:stateHash,model_id:"vendor/a:free"});const registry=join(root,"registry.json");atomicWrite(registry,selectorRegistry(["vendor/a:free","vendor/b:free","vendor/c:free"]));const beforeHash=computeWorktreeStateHash(root),urls:string[]=[];const fetcher=async(input:string)=>{urls.push(input);if(input.includes("/model/"))return new Response(JSON.stringify({data:{...selectorModel("vendor/b:free"),pricing:{prompt:"1",completion:"0",request:"0"}}}),{status:200});return new Response(JSON.stringify({data:[selectorModel("vendor/a:free"),selectorModel("vendor/b:free"),selectorModel("vendor/c:free")],total_count:3}),{status:200})};await assert.rejects(()=>dispatchSelectOnly(root,registry,fetcher),/OPENROUTER_PREFLIGHT_FAILED/);const afterHash=computeWorktreeStateHash(root);assert.equal(afterHash,beforeHash);assert.deepEqual(urls,["https://openrouter.ai/api/v1/models?supported_parameters=tools&input_modalities=text&output_modalities=text&context=32768&max_price=0&max_output_price=0&sort=intelligence-high-to-low&min_coding_index=0","https://openrouter.ai/api/v1/model/vendor/b%3Afree"]);assert.equal(existsSync(paths.lock),false)}finally{rmSync(root,{recursive:true,force:true})}});
test("actual CLI select-only dispatch stops on missing compatibility evidence before preflight",async()=>{const root=gitTestRepo();try{const registry=join(root,"registry.json");atomicWrite(registry,selectorRegistry(["vendor/a:free"]));const beforeHash=computeWorktreeStateHash(root),urls:string[]=[];const fetcher=async(input:string)=>{urls.push(input);return new Response(JSON.stringify({data:[selectorModel("vendor/b:free")],total_count:1}),{status:200})};await assert.rejects(()=>dispatchSelectOnly(root,registry,fetcher),/NO_CURRENT_COMPATIBLE_FREE_MODEL/);const afterHash=computeWorktreeStateHash(root);assert.equal(afterHash,beforeHash);assert.equal(urls.length,1);assert.equal(urls[0].includes("/models?"),true)}finally{rmSync(root,{recursive:true,force:true})}});
test("normal PLAN BUILD REVIEW use the isolated Codex boundary",async()=>{const phases=["plan","build","review"] as const;const seen:any[]=[];const events:any[]=[];const executor:any={execute:async(options:any,thread:any)=>{seen.push({options,thread});return{threadId:"normal-thread",events,finalResponse:"ok"}}};const validFs:any={mkdir(){},lstat(){return{isDirectory:()=>true,isSymbolicLink:()=>false}},exists(){return false}};for(const phase of phases){await runNormalFallbackExecution(phase,executor,"v/m:free","C:\\work","task",{LOCALAPPDATA:"C:\\local",CODEX_HOME:"C:\\caller",OPENROUTER_API_KEY:"free",OPENAI_API_KEY:"paid",CODEX_API_KEY:"secret"},undefined,{filesystem:validFs});}assert.equal(seen.length,3);for(const call of seen){assert.deepEqual(call.options.config,openRouterConfig());assert.equal(call.options.config.agents.enabled,false);assert.equal(call.options.env.CODEX_HOME,"C:\\local\\print-engineer-codex\\openrouter-home-v1");assert.equal(call.options.env.OPENROUTER_API_KEY,"free");assert.equal(call.options.env.OPENAI_API_KEY,undefined);assert.equal(call.options.env.CODEX_API_KEY,undefined);assert.equal(call.options.env.CODEX_HOME,"C:\\local\\print-engineer-codex\\openrouter-home-v1");}const primaryExecutor:any={execute:async()=>({threadId:"primary",events,finalResponse:"ok"})};const primarySeen:any[]=[];await runNormalFallbackExecution("plan",{execute:async(options:any,thread:any)=>{primarySeen.push({options,thread});return primaryExecutor.execute(options,thread);}} as any,"v/m:free","C:\\work","task",{LOCALAPPDATA:"C:\\local",OPENROUTER_API_KEY:"free"},undefined,{filesystem:validFs});assert.equal(primarySeen.length,1);assert.equal(primarySeen[0].options.config.agents.enabled,false);let executions=0;const counting:any={execute:async()=>{executions++;throw new Error("MUST_NOT_REACH_CODEX")}};for(const phase of phases){await assert.rejects(()=>runNormalFallbackExecution(phase,counting,"v/m:free","C:\\work","task",{LOCALAPPDATA:"C:\\local",OPENROUTER_API_KEY:"free"},undefined,{filesystem:{mkdir(){},lstat(){throw new Error("classification")},exists(){return false}}}),/OPENROUTER_CODEX_HOME_INVALID/);await assert.rejects(()=>runNormalFallbackExecution(phase,counting,"v/m:free","C:\\work","task",{LOCALAPPDATA:"C:\\local",OPENROUTER_API_KEY:"free"},undefined,{filesystem:{mkdir(){},lstat(){return{isDirectory:()=>true,isSymbolicLink:()=>false}},exists(){return true}}}),/OPENROUTER_CODEX_HOME_AUTH_PRESENT/);}assert.equal(executions,0)});
test("ordinary PLAN BUILD REVIEW selection all preserve the compatibility registry gate",async()=>{const root=mkdtempSync(join(tmpdir(),"ordinary-gate-"));try{const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:selectorModel("vendor/a:free")}:{data:[selectorModel("vendor/a:free")],total_count:1}),{status:200});const missing=join(root,"missing-registry.json");for(const input of [{phase:"plan" as const,override:"vendor/a:free"},{phase:"build" as const,override:"vendor/a:free"},{phase:"review" as const,reviewTarget:"plan" as const,override:"vendor/a:free",plan:{canonical:"plans/x.md",hash:"a".repeat(64)},planProducerPath:join(root,"plan.json")}]){if(input.phase==="review"){atomicWrite(input.planProducerPath!,{schema_version:1,kind:"plan_producer",plan_path:"plans/x.md",plan_sha256:"a".repeat(64),model_id:"vendor/producer:free"});}await assert.rejects(()=>selectOpenRouter({...input,key:"synthetic",fetcher,registryPath:missing}),/ENOENT|REGISTRY|COMPATIBILITY/);}}finally{rmSync(root,{recursive:true,force:true})}});
import {runCodexTask} from "../src/index.js";

let environmentLock=Promise.resolve();
async function withEnvironmentLock<T>(run:()=>Promise<T>):Promise<T>{let release!:()=>void;const previous=environmentLock;environmentLock=new Promise<void>(resolve=>{release=resolve;});await previous;try{return await run();}finally{release();}}
async function withFallbackEnvironment<T>(values:Record<string,string>,run:()=>Promise<T>):Promise<T>{return withEnvironmentLock(async()=>{const names=["MODEL_PLAN_PATH","LOCALAPPDATA","OPENROUTER_API_KEY","CODEX_HOME","OPENAI_API_KEY","CODEX_API_KEY"];const previous=Object.fromEntries(names.map(name=>[name,process.env[name]]));for(const name of names)delete process.env[name];Object.assign(process.env,values);try{return await run();}finally{for(const name of names){if(previous[name]===undefined)delete process.env[name];else process.env[name]=previous[name];}}});}
function trackedFallbackFilesystem(parent:string,home:string,auth=false){const directories=new Set([parent]);const mkdirPaths:string[]=[];const lstatPaths:string[]=[];return{mkdir(path:string){mkdirPaths.push(path);directories.add(path)},lstat(path:string){lstatPaths.push(path);if(!directories.has(path))throw new Error("MISSING_DIRECTORY");return{isDirectory:()=>true,isSymbolicLink:()=>false}},exists(path:string){assert.equal(path,join(home,"auth.json"));return auth},directories,mkdirPaths,lstatPaths};}
function fallbackExecutor(seen:any[],mutate:()=>void){return{execute:async(options:any,thread:any)=>{seen.push({options,thread});mutate();return{threadId:"fallback-thread",events:[],finalResponse:"ok"};}} as any;}
function taskState(){return{threads:{}} as any;}
