test("pinned SDK serializes the OpenRouter compatibility request without multi-agent namespace tools",async()=>withEnvironmentLock(async()=>{const requests:any[]=[];const server=createServer((request,response)=>{let body="";request.setEncoding("utf8");request.on("data",chunk=>{body+=chunk});request.on("end",()=>{requests.push({method:request.method,url:request.url,headers:request.headers,body:JSON.parse(body)});response.writeHead(400,{"content-type":"application/json","connection":"close"});response.end(JSON.stringify({error:{message:"synthetic loopback failure"}}));});});await new Promise<void>(resolve=>server.listen(0,"127.0.0.1",()=>resolve()));const address=server.address();assert.ok(address&&typeof address!=="string");const baseUrl=`http://127.0.0.1:${address.port}/api/v1`;const config:any=structuredClone(openRouterConfig());config.model_providers.openrouter.base_url=baseUrl;const home=mkdtempSync(join(tmpdir(),"codex-openrouter-loopback-"));try{const {Codex}=await import("@openai/codex-sdk");const codex=new Codex({config,env:{CODEX_HOME:home,OPENROUTER_API_KEY:"synthetic-loopback-key",PATH:process.env.PATH??""}});const thread=codex.startThread({model:"z-ai/glm-5.2:free",workingDirectory:process.cwd(),sandboxMode:"read-only",approvalPolicy:"never",networkAccessEnabled:false,webSearchMode:"disabled"});await assert.rejects(async()=>{const streamed=await thread.runStreamed("Read AGENTS.md and report its first heading.");for await(const _event of streamed.events){}});assert.equal(requests.length,1);const request=requests[0];assert.equal(request.method,"POST");assert.equal(request.url,"/api/v1/responses");assert.equal(request.body.model,"z-ai/glm-5.2:free");assert.equal(request.body.stream,true);assert.equal(request.headers.authorization,"Bearer synthetic-loopback-key");assert.ok(Array.isArray(request.body.tools));const namespaceTools=request.body.tools.filter((tool:any)=>tool.type==="namespace");assert.equal(namespaceTools.length,0);assert.equal(request.body.tools.some((tool:any)=>tool.type==="function"&&tool.name==="shell_command"),true);assert.equal(JSON.stringify(request.body).includes("multi_agent_v1"),false);assert.equal(baseUrl.startsWith("http://127.0.0.1:"),true);assert.equal(request.headers.authorization.includes("OPENROUTER"),false);}finally{server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));rmSync(home,{recursive:true,force:true});}}));
