test("30. PLAN/BUILD/REVIEW producer exclusion behavior is preserved",async()=>{const fixedNow=new Date("2026-08-19T00:00:00.000Z");const root=mkdtempSync(join(tmpdir(),"sel-prod-excl-"));try{
const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:selectorModel("vendor/a:free")}:{data:[selectorModel("vendor/a:free")],total_count:1}),{status:200});
const registry=join(root,"registry.json");
atomicWrite(registry,registryFor(["vendor/a:free"],fixedNow));
const plan=await selectOpenRouter({phase:"plan",key:"synthetic",fetcher,registryPath:registry,now:fixedNow});
assert.equal(plan.modelId,"vendor/a:free");
assert.equal(plan.role,"plan");
assert.equal(plan.selectionMode,"auto");
const build=await selectOpenRouter({phase:"build",key:"synthetic",fetcher,registryPath:registry,now:fixedNow});
assert.equal(build.modelId,"vendor/a:free");
assert.equal(build.role,"build");
assert.equal(build.selectionMode,"auto");
const planProducer=join(root,"plan.json");
atomicWrite(planProducer,{schema_version:1,kind:"plan_producer",plan_path:"plans/x.md",plan_sha256:"a".repeat(64),model_id:"vendor/producer:free"});
const planReviewFetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:selectorModel("vendor/a:free")}:{data:[selectorModel("vendor/producer:free"),selectorModel("vendor/a:free")],total_count:2}),{status:200});
atomicWrite(registry,registryFor(["vendor/producer:free","vendor/a:free"],fixedNow));
const planReview=await selectOpenRouter({phase:"review",reviewTarget:"plan",key:"synthetic",fetcher:planReviewFetcher,registryPath:registry,plan:{canonical:"plans/x.md",hash:"a".repeat(64)},planProducerPath:planProducer,now:fixedNow});
assert.equal(planReview.modelId,"vendor/a:free");
assert.equal(planReview.role,"plan-review");
}finally{rmSync(root,{recursive:true,force:true})}});
test("32. downstream inference failure after successful selection/preflight is preserved; executor runs EXACTLY once; no re-selection",async()=>{const now=new Date("2026-08-19T00:00:00.000Z");const root=mkdtempSync(join(tmpdir(),"sel-infer-fail-"));try{const registry=join(root,"registry.json");atomicWrite(registry,registryFor(["vendor/a:free"],now));const fetcher=async(input:string)=>new Response(JSON.stringify(input.includes("/model/")?{data:selectorModel("vendor/a:free")}:{data:[selectorModel("vendor/a:free")],total_count:1}),{status:200});const selection=await selectOpenRouter({phase:"build",key:"synthetic",fetcher,registryPath:registry,now});assert.equal(selection.modelId,"vendor/a:free");let calls=0;const executor:any={execute:async()=>{calls++;throw new Error("INFERENCE_FAILED")}};const parent="C:\\local\\print-engineer-codex",home=parent+"\\openrouter-home-v1";const fs=trackedFallbackFilesystem(parent,home);await withFallbackEnvironment({LOCALAPPDATA:"C:\\local",OPENROUTER_API_KEY:"free",CODEX_HOME:"C:\\caller"},async()=>{await assert.rejects(()=>runNormalFallbackExecution("build",executor,selection.modelId,root,"task",{LOCALAPPDATA:"C:\\local"},undefined,{filesystem:fs}),/INFERENCE_FAILED/);});assert.equal(calls,1);}finally{rmSync(root,{recursive:true,force:true})}});